input.content:
/* Shared styles for the explainer pages.
   Colour meaning is fixed across every page:
   --input  = PowerCenter / the XML (what we read)
   --convert = our converter (what we build)
   --output = dbt (what we write)
   --warn   = a flag: something odd in the XML that we copy, not fix */

:root {
  --bg: #f7f6f2;
  --surface: #ffffff;
  --surface-2: #efede7;
  --text: #1c1b19;
  --muted: #5c5a54;
  --border: #dcd9d0;
  --code-bg: #f3f1eb;
  --link: #1f5fbf;
  --input: #8f520f;
  --input-soft: #f6ead9;
  --convert: #1f5fbf;
  --convert-soft: #e1eaf8;
  --output: #1c7348;
  --output-soft: #dcefe4;
  --warn: #b42318;
  --warn-soft: #fbe6e3;
  --radius: 10px;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #141413;
    --surface: #1d1d1b;
    --surface-2: #272724;
    --text: #ecebe6;
    --muted: #a9a7a0;
    --border: #3a3935;
    --code-bg: #191917;
    --link: #8ab4f5;
    --input: #e4a95e;
    --input-soft: #3a2c1a;
    --convert: #8ab4f5;
    --convert-soft: #1d2b42;
    --output: #74cc9f;
    --output-soft: #1b3326;
    --warn: #ff8f80;
    --warn-soft: #3f201c;
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #141413;
  --surface: #1d1d1b;
  --surface-2: #272724;
  --text: #ecebe6;
  --muted: #a9a7a0;
  --border: #3a3935;
  --code-bg: #191917;
  --link: #8ab4f5;
  --input: #e4a95e;
  --input-soft: #3a2c1a;
  --convert: #8ab4f5;
  --convert-soft: #1d2b42;
  --output: #74cc9f;
  --output-soft: #1b3326;
  --warn: #ff8f80;
  --warn-soft: #3f201c;
  color-scheme: dark;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.55 var(--sans);
}
a { color: var(--link); }
code, pre, .mono { font-family: var(--mono); font-size: 0.88em; }
:not(pre) > code { background: var(--code-bg); border: 1px solid var(--border); border-radius: 5px; padding: 0 4px; }

/* ---------- header + nav ---------- */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky; top: 0; z-index: 10;
}
.site-header .inner {
  max-width: 1040px; margin: 0 auto; padding: 10px 16px;
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px 20px;
}
.brand { font-weight: 650; text-decoration: none; color: var(--text); white-space: nowrap; }
.brand span { color: var(--muted); font-weight: 500; }
.site-nav { display: flex; flex-wrap: wrap; gap: 4px; }
.site-nav a {
  text-decoration: none; color: var(--muted); padding: 4px 10px; border-radius: 999px; font-size: 14px;
}
.site-nav a:hover { color: var(--text); background: var(--surface-2); }
.site-nav a[aria-current="page"] { color: var(--text); background: var(--surface-2); font-weight: 600; }

main { max-width: 1040px; margin: 0 auto; padding: 28px 16px 64px; }
h1 { font-size: 30px; line-height: 1.2; margin: 0 0 8px; }
h2 { font-size: 22px; margin: 44px 0 10px; }
h3 { font-size: 17px; margin: 22px 0 6px; }
.lead { font-size: 18px; color: var(--muted); margin: 0 0 20px; max-width: 760px; }
.muted { color: var(--muted); }
.small { font-size: 14px; }
section > p, .prose p { max-width: 760px; }

/* ---------- line references to the XML on GitHub ---------- */
a.L {
  font-family: var(--mono); font-size: 0.82em; white-space: nowrap;
  text-decoration: none; border: 1px solid var(--border); border-radius: 5px;
  padding: 0 4px; background: var(--surface-2); color: var(--muted);
}
a.L:hover { color: var(--link); border-color: var(--link); }

/* ---------- glossary term links ---------- */
a.term { color: inherit; text-decoration: underline dotted; text-underline-offset: 3px; position: relative; }
a.term:hover, a.term:focus { color: var(--link); }
.term-tip {
  position: absolute; z-index: 20; max-width: 300px; padding: 8px 10px;
  background: var(--surface); color: var(--text); border: 1px solid var(--border);
  border-radius: 8px; box-shadow: 0 6px 20px rgba(0,0,0,.15); font-size: 14px; line-height: 1.4;
  pointer-events: none;
}
.term-tip b { display: block; margin-bottom: 2px; }

/* ---------- cards ---------- */
.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 14px; }
.card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 16px; border-top: 4px solid var(--border);
}
.card h3 { margin-top: 0; }
.card p { margin: 6px 0; }
.card ul { margin: 6px 0; padding-left: 18px; }
.k-input { border-top-color: var(--input); }
.k-convert { border-top-color: var(--convert); }
.k-output { border-top-color: var(--output); }
.k-warn { border-top-color: var(--warn); }
.tag {
  display: inline-block; font-size: 12px; font-weight: 600; letter-spacing: .02em;
  padding: 1px 8px; border-radius: 999px; background: var(--surface-2); color: var(--muted);
}
.tag.input { background: var(--input-soft); color: var(--input); }
.tag.convert { background: var(--convert-soft); color: var(--convert); }
.tag.output { background: var(--output-soft); color: var(--output); }
.tag.warn { background: var(--warn-soft); color: var(--warn); }

/* ---------- flow diagram (HTML, responsive: row on wide, column on narrow) ---------- */
figure { margin: 18px 0; }
figcaption { color: var(--muted); font-size: 14px; margin-top: 8px; max-width: 760px; }
.flow { display: flex; align-items: stretch; gap: 0; }
.flow-node {
  flex: 1 1 0; min-width: 0;
  background: var(--surface); border: 1.5px solid var(--border); border-radius: var(--radius);
  padding: 12px; font-size: 14px;
}
.flow-node .t { font-weight: 650; font-size: 15px; display: block; margin-bottom: 2px; overflow-wrap: anywhere; }
.flow-node .s { color: var(--muted); font-size: 13px; display: block; overflow-wrap: anywhere; }
.flow-node ul { margin: 6px 0 0; padding-left: 16px; }
.flow-node.input { border-color: var(--input); background: var(--input-soft); }
.flow-node.convert { border-color: var(--convert); background: var(--convert-soft); }
.flow-node.output { border-color: var(--output); background: var(--output-soft); }
.flow-node.dim { opacity: .55; }
.flow-node.hot { box-shadow: 0 0 0 3px var(--convert); }
.flow-arrow {
  flex: 0 0 76px; display: flex; flex-direction: column; align-items: center; justify-content: center;
  color: var(--muted); font-size: 12px; text-align: center; padding: 0 4px;
}
.flow-arrow::after { content: "→"; font-size: 22px; line-height: 1; color: var(--text); }
.flow.tight .flow-arrow { flex-basis: 34px; }
button.flow-node { font: inherit; color: inherit; text-align: left; cursor: pointer; }
button.flow-node:hover { border-color: var(--convert); }
button.flow-node[aria-pressed="true"] { box-shadow: 0 0 0 3px var(--convert); }
@media (max-width: 760px) {
  .flow { flex-direction: column; }
  .flow-arrow { flex-basis: auto; padding: 6px 0; flex-direction: row; gap: 8px; }
  .flow-arrow::after { content: "↓"; }
}

/* ---------- callouts ---------- */
.callout {
  border: 1px solid var(--border); border-left: 4px solid var(--muted);
  background: var(--surface); border-radius: 8px; padding: 12px 14px; margin: 14px 0; max-width: 820px;
}
.callout > :first-child { margin-top: 0; }
.callout > :last-child { margin-bottom: 0; }
.callout.warn { border-left-color: var(--warn); background: var(--warn-soft); }
.callout.decision { border-left-color: var(--output); }
.callout.open { border-left-color: var(--convert); }

/* ---------- tables ---------- */
.table-wrap { overflow-x: auto; border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); }
table.data { border-collapse: collapse; width: 100%; font-size: 14px; }
table.data th, table.data td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--border); vertical-align: top; }
table.data th { background: var(--surface-2); font-weight: 600; white-space: nowrap; }
table.data tr:last-child td { border-bottom: 0; }
table.data td.num { text-align: right; font-variant-numeric: tabular-nums; }
table.data tr.group td { background: var(--surface-2); font-weight: 600; color: var(--muted); font-size: 13px; }
tr.flagged td { background: var(--warn-soft); }

/* ---------- code ---------- */
pre.code {
  background: var(--code-bg); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 12px 0; margin: 10px 0; overflow-x: auto; line-height: 1.5; font-size: 13px;
}
pre.code .row { display: block; padding: 0 14px 0 0; white-space: pre; }
pre.code .ln {
  display: inline-block; width: 4.2em; padding-right: 1em; text-align: right;
  color: var(--muted); user-select: none; opacity: .8;
}
pre.code .row.hl { background: var(--warn-soft); }
pre.code.plain { padding: 12px 14px; white-space: pre; }
.cm { color: var(--muted); }
.flagtxt { color: var(--warn); font-weight: 600; }

/* ---------- tabs ---------- */
.tabs { display: flex; flex-wrap: wrap; gap: 4px; border-bottom: 1px solid var(--border); margin-top: 12px; }
.tabs button {
  font: inherit; font-size: 14px; background: none; border: 1px solid transparent; border-bottom: 0;
  padding: 6px 12px; border-radius: 8px 8px 0 0; color: var(--muted); cursor: pointer;
}
.tabs button[aria-selected="true"] { background: var(--surface); border-color: var(--border); color: var(--text); font-weight: 600; margin-bottom: -1px; }
.tab-panel[hidden] { display: none; }

/* ---------- chips (filters) ---------- */
.chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 10px 0; }
.chips button {
  font: inherit; font-size: 14px; padding: 4px 12px; border-radius: 999px; cursor: pointer;
  border: 1px solid var(--border); background: var(--surface); color: var(--muted);
}
.chips button[aria-pressed="true"] { background: var(--text); color: var(--bg); border-color: var(--text); }
input.search {
  font: inherit; width: 100%; max-width: 420px; padding: 8px 12px; border-radius: 8px;
  border: 1px solid var(--border); background: var(--surface); color: var(--text);
}

/* ---------- detail panel ---------- */
.panel {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 16px; margin-top: 14px;
}
.panel h3 { margin-top: 0; }
.kv { display: grid; grid-template-columns: max-content 1fr; gap: 4px 14px; font-size: 14px; }
.kv dt { color: var(--muted); }
.kv dd { margin: 0; }

/* ---------- stepper ---------- */
.steps { display: flex; gap: 6px; flex-wrap: wrap; margin: 14px 0; }
.steps button {
  font: inherit; flex: 1 1 140px; text-align: left; cursor: pointer;
  border: 1.5px solid var(--border); background: var(--surface); color: var(--text);
  border-radius: var(--radius); padding: 10px 12px;
}
.steps button .n { display: block; font-size: 12px; color: var(--muted); }
.steps button .t { font-weight: 650; }
.steps button[aria-selected="true"] { border-color: var(--convert); background: var(--convert-soft); }
.io { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.io > div { min-width: 0; }
.io h4 { margin: 10px 0 4px; font-size: 13px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }
@media (max-width: 760px) { .io { grid-template-columns: 1fr; } }
.pager { display: flex; justify-content: space-between; gap: 10px; margin-top: 14px; }
.pager button {
  font: inherit; font-size: 14px; padding: 6px 14px; border-radius: 8px; cursor: pointer;
  border: 1px solid var(--border); background: var(--surface); color: var(--text);
}
.pager button:disabled { opacity: .4; cursor: default; }

/* ---------- lineage chain ---------- */
ol.chain { list-style: none; padding: 0; margin: 10px 0; }
ol.chain li {
  position: relative; padding: 6px 10px 6px 28px; font-family: var(--mono); font-size: 13px;
  border-left: 2px solid var(--border); margin-left: 8px;
}
ol.chain li::before {
  content: ""; position: absolute; left: -7px; top: 12px; width: 12px; height: 12px;
  border-radius: 50%; background: var(--surface); border: 2px solid var(--muted);
}
ol.chain li.flag { color: var(--warn); }
ol.chain li.flag::before { border-color: var(--warn); }
ol.chain .why { font-family: var(--sans); color: var(--muted); font-size: 13px; }

/* ---------- inline SVG diagrams ---------- */
svg.diagram { display: block; width: 100%; height: auto; max-width: 560px; color: var(--text); }
svg.diagram text { font-family: var(--mono); font-size: 12px; fill: currentColor; }
svg.diagram .hdr { font-family: var(--sans); font-weight: 650; font-size: 13px; }
svg.diagram .wire { stroke: currentColor; stroke-width: 1.4; fill: none; opacity: .55; }
svg.diagram .wire.flag { stroke: var(--warn); opacity: 1; stroke-width: 2; }
svg.diagram text.flag { fill: var(--warn); font-weight: 600; }
svg.diagram .dot { fill: currentColor; }
svg.diagram .dot.flag { fill: var(--warn); }

footer.page-foot { margin-top: 56px; padding-top: 14px; border-top: 1px solid var(--border); color: var(--muted); font-size: 13px; }

