  border-radius: 50%; background: var(--surface); border: 2px solid var(--muted);
}
ol.chain li.flag { color: var(--warn); }
ol.chain li.flag::before { border-color: var(--warn); }
ol.chain .why { font-family: var(--sans); color: var(--muted); font-size: 13px; }

/* ---------- inline SVG diagrams ---------- */
svg.diagram { display: block; width: 100%; height: auto; max-width: 560px; color: var(--text); }
svg.diagram text { font-family: var(--mono); font-size: 12px; fill: currentColor; }
svg.diagram .hdr { font-family: var(--sans); font-weight: 650; font-size: 13px; }
svg.diagram .wire { stroke: currentColor; stroke-width: 1.4; fill: none; opacity: .55; }
svg.diagram .wire.flag { stroke: var(--warn); opacity: 1; stroke-width: 2; }
svg.diagram text.flag { fill: var(--warn); font-weight: 600; }
svg.diagram .dot { fill: currentColor; }
svg.diagram .dot.flag { fill: var(--warn); }

footer.page-foot { margin-top: 56px; padding-top: 14px; border-top: 1px solid var(--border); color: var(--muted); font-size: 13px; }

