/* The ubiquitous language for this project: one word per idea.
 * Used by glossary.html (full list) and by every page's hover cards (a.term[data-term]).
 *
 * Fields:
 *   id     anchor + key used by data-term
 *   term   the word we use (in code, tests, README and chat)
 *   group  "PowerCenter" | "dbt & SQL" | "Our converter"
 *   def    one plain line (shown in hover cards)
 *   more   optional second line
 *   becomes optional: what it turns into on the other side
 *   xml    optional: where to see it in the demo XML ("L161" style refs become links)
 *   avoid  optional: words we do not use for this, or a clash to watch
 */
window.GLOSSARY = [
  /* ---------------- PowerCenter (what we read) ---------------- */
  { id: "repository", group: "PowerCenter", term: "Repository",
    def: "The PowerCenter database that stores every object. Our XML file is an export of one.",
    xml: "<REPOSITORY> L4" },
  { id: "folder", group: "PowerCenter", term: "Folder",
    def: "A project inside the repository. It holds the sources, targets, mappings and workflow.",
    xml: "<FOLDER> L5" },
  { id: "pc-source", group: "PowerCenter", term: "PC Source (Source Definition)",
    def: "Describes a table PowerCenter reads: its name, schema (owner) and columns. It is a description, not data.",
    becomes: "A table in dbt sources.yml, or a ref() when another mapping writes that table.",
    xml: "<SOURCE> RAW_ORDERS at L26",
    avoid: "Never say just \"source\": dbt also has sources. Say PC Source or dbt source." },
  { id: "pc-target", group: "PowerCenter", term: "PC Target (Target Definition)",
    def: "Describes a table that a mapping writes to.",
    becomes: "One dbt model per PC Target.",
    xml: "<TARGET> STG_ORDERS at L67",
    avoid: "In dbt, \"target\" means a connection environment (dev, prod). Say PC Target." },
  { id: "mapping", group: "PowerCenter", term: "Mapping",
    def: "The drawing of one pipeline: instances wired together from PC Sources to PC Targets. This is the unit we convert.",
    more: "This file has 3. m_FL_JS_STAGING_FULL alone writes 6 PC Targets.",
    becomes: "Several dbt models, one per PC Target it writes.",
    xml: "<MAPPING> L90, L1210, L3107" },
  { id: "transformation", group: "PowerCenter", term: "Transformation",
    def: "One box in a mapping that does one job (read, compute, filter, join, group, sort...). It has ports.",
    more: "98 in this file.",
    becomes: "Usually one CTE.",
    xml: "<TRANSFORMATION> EXP_ORDERS at L106",
    avoid: "Not \"step\" or \"node\". Node is our graph word, see Mapping graph." },
  { id: "instance", group: "PowerCenter", term: "Instance",
    def: "A placed copy of a PC Source, PC Target or transformation inside a mapping. Connectors point at instance names.",
    more: "One table can appear twice. RAW_PRODUCTS1 is a second instance of RAW_PRODUCTS.",
    xml: "<INSTANCE> L577" },
  { id: "port", group: "PowerCenter", term: "Port",
    def: "A column on a transformation. Its port type is INPUT, OUTPUT, INPUT/OUTPUT or LOCAL VARIABLE.",
    becomes: "A column in the CTE.",
    xml: "<TRANSFORMFIELD> L107",
    avoid: "Say port inside a transformation and column on a table." },
  { id: "variable-port", group: "PowerCenter", term: "Variable port",
    def: "A helper value inside an Expression transformation. It can remember the previous row, which plain SQL cannot do.",
    becomes: "Usually a window function, e.g. row_number() over (partition by ... order by ...).",
    xml: "v_ORDER_SEQUENCE at L3588–3590" },
  { id: "connector", group: "PowerCenter", term: "Connector",
    def: "Joins one output port to one input port. Connectors are the only truth about where data goes.",
    more: "1,066 in this file. In plain talk we also say \"wire\".",
    xml: "<CONNECTOR> L643",
    avoid: "Not \"link\": a link is between workflow tasks." },
  { id: "port-expression", group: "PowerCenter", term: "Port expression",
    def: "The formula on an output or variable port, in Informatica's own language (IIF, ISNULL, TO_DATE...).",
    more: "384 in this file: 270 pass-through, 114 with real logic. Router conditions (5) are separate.",
    becomes: "A SQL expression in the select list.",
    xml: "EXPRESSION attribute, e.g. L111",
    avoid: "Not the same as the Expression transformation (the box)." },
  { id: "source-qualifier", group: "PowerCenter", term: "Source Qualifier (SQ)",
    def: "Reads rows from a PC Source into the mapping. It can hold a SQL override, a filter, a join or distinct.",
    more: "28 in this file, and none uses any of those options.",
    becomes: "The first CTE: select the columns from source() or ref().",
    xml: "SQ_RAW_ORDERS at L161–180" },
  { id: "expression-tx", group: "PowerCenter", term: "Expression transformation",
    def: "Computes new columns row by row from port expressions.",
    becomes: "select ..., <expression> as <port>",
    xml: "EXP_ORDERS at L106–125" },
  { id: "filter", group: "PowerCenter", term: "Filter",
    def: "Keeps only the rows where its condition is true.",
    becomes: "where <condition>",
    xml: "NOT ISNULL(LOCATION_ID) at L2385" },
  { id: "joiner", group: "PowerCenter", term: "Joiner",
    def: "Joins two inputs, called master and detail, on a condition.",
    more: "16 in this file: 6 Normal Join, 10 Master Outer Join.",
    becomes: "join ... on ...",
    xml: "SKU1 = SKU at L488" },
  { id: "master-detail", group: "PowerCenter", term: "Master / Detail",
    def: "The two sides of a Joiner. A Master Outer Join keeps every detail row plus the master rows that match.",
    becomes: "detail LEFT JOIN master. Easy to flip by mistake.",
    xml: "Master Outer Join at L1350" },
  { id: "aggregator", group: "PowerCenter", term: "Aggregator",
    def: "Groups rows and computes SUM, COUNT, MAX and so on per group.",
    more: "A port that is neither grouped nor aggregated returns the value from the last row of the group. SQL has no direct match.",
    becomes: "group by",
    xml: "SUM(SUPPLY_COST) at L1443" },
  { id: "sorter", group: "PowerCenter", term: "Sorter",
    def: "Sorts rows. Row order means nothing in a table, so it is usually dropped.",
    more: "It matters when a later box depends on order (variable ports) or when Distinct=YES. None of the 15 here use Distinct.",
    becomes: "Nothing, or the ORDER BY inside a window function.",
    xml: "SRT_ORDERS at L513–533" },
  { id: "router", group: "PowerCenter", term: "Router",
    def: "Sends each row to output groups by condition. Rows that match no group go to DEFAULT.",
    becomes: "One where clause per group.",
    xml: "REGION = 'APAC' at L276" },
  { id: "union", group: "PowerCenter", term: "Union",
    def: "Merges several inputs into one stream. In the XML it shows up as TYPE=\"Custom Transformation\".",
    becomes: "union all",
    xml: "UN_REGIONS at L368" },
  { id: "session", group: "PowerCenter", term: "Session",
    def: "A runnable task that runs one mapping, with its connections and load settings (bulk load, truncate...).",
    becomes: "Roughly a dbt run of that mapping's models, plus materialization config.",
    xml: "<SESSION> s_FL_JS_STAGING_FULL at L811" },
  { id: "workflow", group: "PowerCenter", term: "Workflow",
    def: "Runs tasks in a set order: Start, then the sessions, then a command.",
    becomes: "dbt works out order itself from ref(), so mostly not needed.",
    xml: "<WORKFLOW> L4054" },
  { id: "workflow-link", group: "PowerCenter", term: "Workflow link",
    def: "An arrow between two tasks in a workflow, setting what runs next.",
    xml: "<WORKFLOWLINK> L4623–4625" },
  { id: "command-task", group: "PowerCenter", term: "Command task",
    def: "Runs a shell command from a workflow. The one here runs a SQL script after the last session.",
    more: "Its command contains a plaintext credential. We never show, copy or commit its value.",
    xml: "<TASK> cmd_FL_JS_CREATE_RPT_VIEWS at L4058 (name only)" },

  /* ---------------- dbt & SQL (what we write) ---------------- */
  { id: "dbt", group: "dbt & SQL", term: "dbt",
    def: "A tool that builds tables in a warehouse from SELECT statements. The warehouse does the work; dbt runs the SQL in the right order." },
  { id: "dbt-project", group: "dbt & SQL", term: "dbt project",
    def: "A folder with dbt_project.yml plus models/, seeds/, macros/ and tests." },
  { id: "model", group: "dbt & SQL", term: "Model",
    def: "One .sql file holding one SELECT. dbt builds it as a table or view named after the file.",
    more: "Example: models/staging/stg_orders.sql builds stg_orders." },
  { id: "dbt-source", group: "dbt & SQL", term: "dbt source",
    def: "A raw table declared in sources.yml and read with {{ source('raw', 'raw_orders') }}.",
    avoid: "Clashes with PC Source. Always say which one." },
  { id: "ref", group: "dbt & SQL", term: "ref()",
    def: "{{ ref('stg_orders') }} points at another model. dbt uses refs to work out build order.",
    more: "A table that is a PC Target in one mapping and a PC Source in the next becomes a ref." },
  { id: "dag", group: "dbt & SQL", term: "DAG",
    def: "The dependency graph of models, built from ref() and source(). It decides run order." },
  { id: "materialization", group: "dbt & SQL", term: "Materialization",
    def: "How a model is stored: table (rebuilt every run), view, incremental, or ephemeral." },
  { id: "cte", group: "dbt & SQL", term: "CTE",
    def: "A named step inside one SELECT: with step_name as (select ...). We plan one CTE per transformation." },
  { id: "seed", group: "dbt & SQL", term: "Seed",
    def: "A CSV file that dbt loads as a table. jaffle-shop's raw data ships as seeds." },
