  { id: "dbt-target", group: "dbt & SQL", term: "dbt target / profile",
    def: "profiles.yml holds database connections. A dbt target is one environment in it, like dev or prod.",
    avoid: "Not a PC Target." },
  { id: "adapter", group: "dbt & SQL", term: "Adapter",
    def: "dbt's plugin for one database: dbt-duckdb, dbt-snowflake, and so on." },
  { id: "duckdb", group: "dbt & SQL", term: "DuckDB",
    def: "A small database that runs inside your process and lives in one file. We run and compare models in it." },

  /* ---------------- Our converter (what we build) ---------------- */
  { id: "converter", group: "Our converter", term: "Converter",
    def: "Our tool: it reads a PowerCenter mapping XML and writes dbt models." },
