    def: "Turn each node into a CTE and each port expression into SQL (IIF to CASE WHEN, ISNULL(x) to x IS NULL...)." },
  { id: "write", group: "Our converter", term: "Write (step 5)",
    def: "Write the .sql model files, sources.yml, and a list of flags." },
