python3 -I - <<'EOF'
import re, html, glob
xml = open("external/flowline-pwc-demo/FLOWLINE_DEMO_JAFFLESHOP.xml", encoding="cp1252").read().split("\n")
src = {f: open(f, encoding="utf-8").read() for f in glob.glob("docs/*.html") + ["docs/assets/glossary-data.js"]}
# 1) glossary term ids used vs defined
ids = set(re.findall(r'id: "([^"]+)"', src["docs/assets/glossary-data.js"]))
used = set()
for f, s in src.items():
    used |= set(re.findall(r'data-term="([^"]+)"', s)) | set(re.findall(r'term: "([a-z-]+)"', s) if f.endswith(".html") else [])
print("undefined terms:", sorted(used - ids) or "none")
# 2) every hand-typed L-ref (in .L links and in plain 'Lnnn' text) -> what is on that line
refs = set()
for f, s in src.items():
    for a, b in re.findall(r'\bL(\d{1,4})(?:[–-](\d{1,4}))?\b', s):
        refs.add(int(a))
        if b: refs.add(int(b))
for n in sorted(refs):
    t = xml[n-1].strip()
    if "VALUEPAIR" in t:
        print(n, "<<credential line - not printed>>"); continue
    tag = re.match(r"</?(\w+)", t)
    attrs = dict(re.findall(r'([A-Z_]+) ="([^"]*)"', t))
    keep = {k: html.unescape(v)[:60] for k, v in attrs.items() if k in ("NAME","TYPE","EXPRESSION","VALUE","FROMINSTANCE","FROMFIELD","TOFIELD","FROMTASK","TOTASK","SCHEDULETYPE","CONNECTIONNAME","TRANSFORMATION_NAME")}
    print(n, tag.group(0) if tag else t[:40], keep)
EOF

