      var row = document.createElement("span");
      row.className = "row" + (hl.indexOf(pair[0]) >= 0 ? " hl" : "");
      var ln = document.createElement("span");
      ln.className = "ln";
      ln.textContent = pair[0] == null ? "…" : String(pair[0]);
