/* Shared styles for the explainer pages.
   Colour meaning is fixed across every page:
   --input  = PowerCenter / the XML (what we read)
   --convert = our converter (what we build)
   --output = dbt (what we write)
   --warn   = a flag: something odd in the XML that we copy, not fix */

:root {
  --bg: #f7f6f2;
  --surface: #ffffff;
  --surface-2: #efede7;
  --text: #1c1b19;
  --muted: #5c5a54;
  --border: #dcd9d0;
  --code-bg: #f3f1eb;
  --link: #1f5fbf;
  --input: #8f520f;
  --input-soft: #f6ead9;
  --convert: #1f5fbf;
  --convert-soft: #e1eaf8;
  --output: #1c7348;
  --output-soft: #dcefe4;
  --warn: #b42318;
  --warn-soft: #fbe6e3;
  --radius: 10px;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #141413;
    --surface: #1d1d1b;
    --surface-2: #272724;
    --text: #ecebe6;
    --muted: #a9a7a0;
    --border: #3a3935;
    --code-bg: #191917;
    --link: #8ab4f5;
    --input: #e4a95e;
    --input-soft: #3a2c1a;
    --convert: #8ab4f5;
    --convert-soft: #1d2b42;
    --output: #74cc9f;
    --output-soft: #1b3326;
    --warn: #ff8f80;
    --warn-soft: #3f201c;
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #141413;
  --surface: #1d1d1b;
  --surface-2: #272724;
  --text: #ecebe6;
  --muted: #a9a7a0;
  --border: #3a3935;
  --code-bg: #191917;
  --link: #8ab4f5;
  --input: #e4a95e;
  --input-soft: #3a2c1a;
  --convert: #8ab4f5;
  --convert-soft: #1d2b42;
  --output: #74cc9f;
  --output-soft: #1b3326;
  --warn: #ff8f80;
  --warn-soft: #3f201c;
  color-scheme: dark;
}

* { box-sizing: border-box; }
  .g-item .avoid { color: var(--warn); }
  .g-count { color: var(--muted); font-size: 14px; margin-left: 4px; }
</style>
