def fwd(m, inst, field, seen, hits):
    I={i.get("NAME"):i for i in m.kids("INSTANCE")}
    for c in m.kids("CONNECTOR"):
        if c.get("FROMINSTANCE")==inst and c.get("FROMFIELD")==field:
            ti,tf=c.get("TOINSTANCE"),c.get("TOFIELD")
            if (ti,tf) in seen: continue
            seen.add((ti,tf))
            i=I[ti]
            if i.get("TYPE")=="TARGET": hits.add((i.get("TRANSFORMATION_NAME"),tf)); continue
            d=next(x for x in m.kids("TRANSFORMATION") if x.get("NAME")==i.get("TRANSFORMATION_NAME"))
            ps=d.kids("TRANSFORMFIELD")
            # same port continues if INPUT/OUTPUT; else any port whose expression mentions it (incl. variables, transitively)
            frontier=[tf]; done=set()
            while frontier:
                p=frontier.pop(); 
                if p in done: continue
                done.add(p)
                pp=next((x for x in ps if x.get("NAME")==p),None)
                if pp is not None and "OUTPUT" in pp.get("PORTTYPE",""): fwd(m,ti,p,seen,hits)
                for x in ps:
                    if x.get("NAME")!=p and re.search(r"\b"+re.escape(p)+r"\b",x.get("EXPRESSION") or ""): frontier.append(x.get("NAME"))
