    out=[]; I={i.get("NAME"):i for i in m.kids("INSTANCE")}
    while True:
        i=I[inst]
        if i.get("TYPE")!="TRANSFORMATION": out.append(f"{inst}.{field}"); break
        d=next(x for x in m.kids("TRANSFORMATION") if x.get("NAME")==i.get("TRANSFORMATION_NAME"))
