            if len(names)!=1: out.append(f"  (stops: {names})"); break
            field=names[0]; continue
        c=next((c for c in m.kids("CONNECTOR") if c.get("TOINSTANCE")==inst and c.get("TOFIELD")==field),None)
        if c is None: break
        inst,field=c.get("FROMINSTANCE"),c.get("FROMFIELD")
    return out
