        if a.get("NAME") in ("Treat source rows as","Commit Type","Commit Interval","Stop on errors","Session Log File Name","$Source connection value","$Target connection value"): print("   ",a.get("NAME"),"=",a.get("VALUE"),"L",a.start)
    for x in s.kids("SESSIONEXTENSION"):
        if x.get("TRANSFORMATIONTYPE") in ("Target Definition","Source Definition","Source Qualifier"):
            cr=x.kids("CONNECTIONREFERENCE"); 
            atts={a.get("NAME"):(a.get("VALUE"),a.start) for a in x.kids("ATTRIBUTE")}
            keep={k:v for k,v in atts.items() if k in ("Truncate target table option","Target load type","Insert","Update as Update","Delete","Reject file name")}
