import sys,re; sys.path.insert(0, sys.argv[1])
from pcxml import parse
r=parse("external/flowline-pwc-demo/FLOWLINE_DEMO_JAFFLESHOP.xml"); f=r.kids("REPOSITORY")[0].kids("FOLDER")[0]
for m in f.kids("MAPPING"):
    for t in m.kids("TRANSFORMATION"):
        ps=t.kids("TRANSFORMFIELD"); names=[p.get("NAME") for p in ps]
        vs=[p for p in ps if p.get("PORTTYPE")=="LOCAL VARIABLE"]
        for i,p in enumerate(ps):
            if p.get("PORTTYPE")!="LOCAL VARIABLE": continue
            refs=set(re.findall(r"[A-Za-z_]\w*",p.get("EXPRESSION") or ""))
            selfref=p.get("NAME") in refs
            later=[v.get("NAME") for v in vs if v.get("NAME") in refs and names.index(v.get("NAME"))>i]
            earlier=[v.get("NAME") for v in vs if v.get("NAME") in refs and names.index(v.get("NAME"))<i]
            if selfref or later:
                print(f"{m.get('NAME')} {t.get('NAME')} L{p.start} {p.get('NAME')} = {p.get('EXPRESSION')!r}\n    self={selfref} uses_later(prev row)={later} uses_earlier(this row)={earlier}")
                for v in vs:
                    if v.get('NAME') in earlier: print(f"      earlier var L{v.start} {v.get('NAME')} = {v.get('EXPRESSION')!r}")
# where does CUSTOMER_ORDER_NUMBER end up
for m in f.kids("MAPPING"):
    for c in m.kids("CONNECTOR"):
        if c.get("FROMFIELD").startswith("CUSTOMER_ORDER_NUMBER") and c.get("TOINSTANCETYPE")=="Target Definition":
            print(m.get("NAME"),"L",c.start,c.get("FROMINSTANCE"),"->",c.get("TOINSTANCE"),c.get("TOFIELD"))
EOF

