import sys,re; sys.path.insert(0, sys.argv[1])
from pcxml import parse
r=parse("external/flowline-pwc-demo/FLOWLINE_DEMO_JAFFLESHOP.xml"); f=r.kids("REPOSITORY")[0].kids("FOLDER")[0]
maps={m.get("NAME"):m for m in f.kids("MAPPING")}
print("## Generic check: a variable copies a port, and a LATER port compares the copy with that same port")
for m in f.kids("MAPPING"):
    for t in m.kids("TRANSFORMATION"):
        ps=t.kids("TRANSFORMFIELD"); order=[p.get("NAME") for p in ps]
        # evaluation order: inputs first, then variables in display order, then outputs
        for i,v in enumerate(ps):
            if v.get("PORTTYPE")!="LOCAL VARIABLE": continue
            src=(v.get("EXPRESSION") or "").strip()
            if src not in order or src==v.get("NAME"): continue
            for w in ps:
                if w is v: continue
                e=w.get("EXPRESSION") or ""
                if re.search(r"\b"+re.escape(v.get("NAME"))+r"\b",e) and re.search(r"\b"+re.escape(src)+r"\b",e):
                    later = (w.get("PORTTYPE")=="LOCAL VARIABLE" and order.index(w.get("NAME"))>i) or w.get("PORTTYPE")=="OUTPUT"
                    print(f"  {m.get('NAME')} {t.get('NAME')}: L{v.start} {v.get('NAME')} = {src}; L{w.start} {w.get('NAME')} compares it with {src} -> {'ALWAYS EQUAL (copy already updated)' if later else 'reads previous row (ok)'}")
# where IS_FIRST_CUSTOMER goes
m=maps["m_FL_JS_MARTS_ENRICHED"]
print("\n## IS_FIRST_CUSTOMER downstream")
for c in m.kids("CONNECTOR"):
    if c.get("FROMINSTANCE")=="EXP_MARK_FIRST_CUSTOMER" and c.get("FROMFIELD")=="IS_FIRST_CUSTOMER": print("  L",c.start,"->",c.get("TOINSTANCE"),c.get("TOFIELD"))
    if c.get("TOINSTANCE")=="EXP_MARK_FIRST_CUSTOMER" and c.get("TOFIELD")=="LOCATION_ID": print("  fed by L",c.start,c.get("FROMINSTANCE"))
