import sys; sys.path.insert(0, sys.argv[1])
from pcxml import parse
from collections import defaultdict
r=parse("external/flowline-pwc-demo/FLOWLINE_DEMO_JAFFLESHOP.xml"); f=r.kids("REPOSITORY")[0].kids("FOLDER")[0]
for m in f.kids("MAPPING"):
    I={i.get("NAME"):i for i in m.kids("INSTANCE")}
    T={t.get("NAME"):t for t in m.kids("TRANSFORMATION")}
    down=defaultdict(set)
    for c in m.kids("CONNECTOR"): down[c.get("FROMINSTANCE")].add(c.get("TOINSTANCE"))
    def kind(n):
        i=I[n]
        if i.get("TYPE")=="TARGET": return "TARGET "+i.get("TRANSFORMATION_NAME")
        t=T[i.get("TRANSFORMATION_NAME")]; ty=t.get("TYPE")
        if ty=="Joiner":
            ta=t.attrs_table(); return f"{n}[{ta['Join Type'][0]}: {ta['Join Condition'][0]}]"
        if ty=="Filter": return f"{n}[Filter: {t.attrs_table()['Filter Condition'][0]}]"
        if ty=="Aggregator": return f"{n}[Agg by {','.join(p.get('NAME') for p in t.kids('TRANSFORMFIELD') if p.get('EXPRESSIONTYPE')=='GROUPBY')}]"
        return None
    def side(j, frm):
        t=T[I[j].get("TRANSFORMATION_NAME")]
        mp={p.get("NAME") for p in t.kids("TRANSFORMFIELD") if "MASTER" in p.get("PORTTYPE","")}
        tf={c.get("TOFIELD") for c in m.kids("CONNECTOR") if c.get("FROMINSTANCE")==frm and c.get("TOINSTANCE")==j}
        return "master" if tf and tf<=mp else ("detail" if not (tf & mp) else "both")
    def paths(n, prev, depth=0, out=None):
        out = out if out is not None else []
        for d in sorted(down[n]):
            k=kind(d)
            if k:
                s=(" via "+side(d,n)+" side") if I[d].get("TYPE")!="TARGET" and T[I[d].get("TRANSFORMATION_NAME")].get("TYPE")=="Joiner" else ""
                out.append("   "*depth+"-> "+k+s)
                if not k.startswith("TARGET") and depth<6: paths(d, n, depth+1, out)
            else:
                paths(d, n, depth, out)
        return out
    for t in m.kids("TRANSFORMATION"):
        if t.get("TYPE")=="Joiner" and t.attrs_table()["Join Type"][0]=="Master Outer Join" and t.get("NAME") in ("JNR_ADD_CUSTOMERS","JNR_ADD_LOCATIONS","JNR_ADD_SUPPLIES","JNR_ADD_LOCATION_INFO","JNR_ADD_SUPPLY_COST","JNR_ITEMS_SUPPLIES"):
            print(f"\n## {m.get('NAME')[9:]} {t.get('NAME')} (L{t.start})")
            seen=set(); 
            for line in paths(t.get("NAME"), None):
                if line not in seen: seen.add(line); print(line)
EOF

