  <p class="small muted">Match: every row has the same value. Explained: the values (or rows) differ for a reason listed in <code>tests/reference/expected_differences.yml</code>. Unexplained: a difference with no reason, which fails the test.</p>

  <div id="sections"></div>

  <footer class="page-foot">Built from <code>out/</code> (written by <code>pc2dbt convert</code>) and <code>tests/reference/results/*.json</code> (written by <code>pytest -m reference</code>), by <code>tools/docs/build_results_data.py</code>.</footer>''')
start = s.index("  var lead = document.getElementById(\"lead\");")
end = s.index("  if (location.hash)")
s = s[:start] + '''  var lead = document.getElementById("lead");
  lead.textContent = "Each mapping converted by pc2dbt, built with dbt on DuckDB, and compared with " + R.reference + " on the same seed data.";

  function counts(t) {
    var c = { matched: 0, explained: 0, unexplained: 0, "not compared": 0 };
    (t.comparison ? t.comparison.columns : []).forEach(function (x) { c[x.status === "stale" ? "unexplained" : x.status]++; });
    return c;
  }
  function rowsText(rows) {
    var t = fmt(rows.ours) + " / " + fmt(rows.reference);
    if (rows.status === "explained") t += " (" + fmt(rows.only_reference + rows.only_ours) + " explained)";
    else if (rows.status !== "matched") t += " (unexplained)";
    return t;
  }

  var root = document.getElementById("sections");
  R.sections.forEach(function (sec) {
    var h2 = h("h2"); h2.id = sec.mapping;
    h2.appendChild(document.createTextNode(sec.mapping + " "));
    var a = h("a", "L", "L" + sec.mapping_lines[0] + "–" + sec.mapping_lines[1]); h2.appendChild(a);
    Site.linkLines(h2);
    root.appendChild(h2);

    var wrap0 = h("div", "table-wrap"), sumt = h("table", "data");
    sumt.innerHTML = "<thead><tr><th>Table</th><th>Rows (ours / jaffle-shop)</th><th>Match</th><th>Explained</th><th>Unexplained</th><th>Not compared</th></tr></thead>";
    var sum = h("tbody");
    sec.tables.forEach(function (t) {
      var c = counts(t), rows = t.comparison ? t.comparison.rows : null;
      var tr = h("tr");
      var td = h("td"); var link = h("a", null, t.name); link.href = "#" + t.name; td.appendChild(link); tr.appendChild(td);
      tr.appendChild(h("td", null, rows ? rowsText(rows) : "not compared"));
      ["matched", "explained", "unexplained", "not compared"].forEach(function (k) { tr.appendChild(h("td", "num", String(c[k]))); });
      sum.appendChild(tr);
    });
    sumt.appendChild(sum); wrap0.appendChild(sumt); root.appendChild(wrap0);

    sec.tables.forEach(function (t) {
      var c = counts(t), rows = t.comparison.rows;
      var d = h("details", "tbl"); d.id = t.name;
      var s = h("summary", null, t.name + " ");
      s.appendChild(h("span", "muted", "· " + fmt(rows.ours) + " rows · " + c.matched + " match · " + c.explained + " explained · " + c.unexplained + " unexplained"));
      d.appendChild(s);
      var inner = h("div", "inner");

      inner.appendChild(h("h3", null, "Compared with jaffle-shop"));
      if (rows.status !== "matched") {
        var rp = h("p");
        rp.appendChild(document.createTextNode("Rows: " + fmt(rows.only_reference) + " only in jaffle-shop, " + fmt(rows.only_ours) + " only in ours. "));
        rp.appendChild(Site.textWithLines(rows.reason || "No reason listed: this fails the test."));
        inner.appendChild(rp);
      }
      var wrap = h("div", "table-wrap"), tb = h("table", "data");
      tb.innerHTML = "<thead><tr><th>Our column</th><th>jaffle-shop column</th><th>Result</th><th>Rows that differ</th><th>Why</th></tr></thead>";
      var body = h("tbody");
      t.comparison.columns.forEach(function (x) {
        var tr = h("tr");
        tr.appendChild(h("td", null, x.ours || "—"));
        tr.appendChild(h("td", null, x.reference || "—"));
        var cls = x.status === "not compared" ? "not" : x.status;
        tr.appendChild(h("td", "status " + cls, LABEL[x.status] || x.status));
        tr.appendChild(h("td", "num", fmt(x.differing_rows)));
        var why = h("td"); why.appendChild(Site.textWithLines(x.reason || "")); tr.appendChild(why);
        body.appendChild(tr);
      });
      tb.appendChild(body); wrap.appendChild(tb); inner.appendChild(wrap);

      inner.appendChild(h("h3", null, "Each box next to the SQL it became"));
      t.blocks.forEach(function (b) {
