        title.appendChild(document.createTextNode(b.box + " · " + b.kind + " · "));
        title.appendChild(h("a", "L", "L" + b.lines[0] + "–" + b.lines[1]));
        if (b.note) title.appendChild(document.createTextNode(" · " + b.note));
        Site.linkLines(title);
        inner.appendChild(title);
        var pair = h("div", "pair");
