    if i.type != "TRANSFORMATION": continue
    t = m.transformations[i.definition]
    print(f"== {i.name} {t.type} L{t.line}-{t.end}")
    for k, (v, l) in t.attributes.items():
        if k in KEEP and v not in ("", "NO") or k in ("Join Type", "Case Sensitive", "Null Treated Low"):
            print(f"   @{k}={v!r} L{l}")
    for g in t.groups:
        print(f"   GROUP {g.name} {g.group_type} {g.expression!r} L{g.line}")
