        e = p.expression if p.expression and p.expression.upper() != p.name.upper() else ""
        d = p.default if p.default and p.default.upper() not in ("NULL", "ERROR('TRANSFORMATION ERROR')") else ""
        print(f"   L{p.line} {p.port_type:20} {p.name:28} {p.datatype}({p.precision},{p.scale}){extra}" + (f" = {e}" if e else "") + (f" def={d!r}" if d else "") + (f" grp={p.group}" if p.group and t.type=='Router' else "") + s)
print("== TARGET connectors")
for c in m.connectors:
    if m.instances[c.to_instance].type == "TARGET":
        print(f"   L{c.line} {c.from_instance}.{c.from_field} -> {c.to_instance}.{c.to_field}")
